"use client"

import { useEffect, useRef, useState } from "react"
import { CheckCircle } from "lucide-react"
import { cn } from "@/lib/utils"

const highlights = [
  "Persoonlijke aanpak en advies op maat",
  "Vakkundige uitvoering met moderne machines",
  "Duurzame materialen en oplossingen",
  "Transparante prijzen zonder verrassingen",
  "Netjes opleveren en opruimen",
  "Nazorg en garantie op ons werk",
]

const stats = [
  { value: "10+", label: "Jaar Ervaring" },
  { value: "500+", label: "Tevreden Klanten" },
  { value: "100%", label: "Tevredenheidsgarantie" },
  { value: "1", label: "Aanspreekpunt" },
]

export function About() {
  const [isVisible, setIsVisible] = useState(false)
  const sectionRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
        }
      },
      { threshold: 0.1 }
    )

    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }

    return () => observer.disconnect()
  }, [])

  return (
    <section ref={sectionRef} id="over-ons" className="py-20 md:py-32 relative overflow-hidden">
      {/* Background decoration */}
      <div className="absolute bottom-0 right-0 w-[600px] h-[600px] bg-primary/5 rounded-full blur-3xl translate-x-1/3 translate-y-1/3" />

      <div className="container mx-auto px-4 relative">
        <div className="grid lg:grid-cols-2 gap-12 lg:gap-20 items-center">
          {/* Content */}
          <div className={cn(
            "transition-all duration-700",
            isVisible ? "opacity-100 translate-x-0" : "opacity-0 -translate-x-8"
          )}>
            <p className="text-sm font-semibold text-primary uppercase tracking-wider mb-3">
              Over Ons
            </p>
            <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-6 text-balance">
              Vakmanschap met <span className="gradient-text">passie voor groen</span>
            </h2>
            <div className="space-y-4 text-muted-foreground mb-8">
              <p>
                Van de Voort Grondwerken is al jarenlang uw betrouwbare partner 
                voor tuinaanleg, grondwerk en onderhoud. Met onze ervaring en 
                moderne uitrusting realiseren wij projecten van klein tot groot.
              </p>
              <p>
                Wat ons drijft? De passie om tuinen tot leven te brengen en 
                grondwerk vakkundig uit te voeren. Wij geloven in persoonlijk 
                contact, heldere afspraken en werk waar u jaren plezier van heeft.
              </p>
            </div>

            {/* Highlights */}
            <div className="grid sm:grid-cols-2 gap-3">
              {highlights.map((highlight, index) => (
                <div 
                  key={index} 
                  className={cn(
                    "flex items-start gap-3 transition-all duration-500",
                    isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-4"
                  )}
                  style={{ transitionDelay: isVisible ? `${(index + 3) * 100}ms` : "0ms" }}
                >
                  <div className="w-5 h-5 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                    <CheckCircle className="w-3.5 h-3.5 text-primary" />
                  </div>
                  <span className="text-sm text-foreground">{highlight}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Stats Card */}
          <div className={cn(
            "relative transition-all duration-700 delay-200",
            isVisible ? "opacity-100 translate-x-0" : "opacity-0 translate-x-8"
          )}>
            <div className="bg-card/80 backdrop-blur-sm border border-border rounded-3xl p-8 md:p-10 shadow-xl shadow-primary/5">
              <div className="grid grid-cols-2 gap-6">
                {stats.map((stat, index) => (
                  <div 
                    key={index} 
                    className={cn(
                      "text-center p-5 rounded-2xl bg-gradient-to-br from-secondary to-secondary/50 hover:from-primary/10 hover:to-primary/5 transition-all duration-300 group",
                      isVisible ? "opacity-100 scale-100" : "opacity-0 scale-95"
                    )}
                    style={{ transitionDelay: isVisible ? `${(index + 4) * 100}ms` : "0ms" }}
                  >
                    <p className="text-4xl md:text-5xl font-bold gradient-text mb-2 group-hover:scale-110 transition-transform">
                      {stat.value}
                    </p>
                    <p className="text-sm text-muted-foreground">{stat.label}</p>
                  </div>
                ))}
              </div>
              <div className="mt-8 pt-6 border-t border-border">
                <blockquote className="text-center">
                  <p className="text-foreground italic mb-2">
                    &ldquo;Wij staan voor kwaliteit, betrouwbaarheid en een persoonlijke aanpak.&rdquo;
                  </p>
                  <cite className="text-sm text-muted-foreground not-italic">
                    — Van de Voort Grondwerken
                  </cite>
                </blockquote>
              </div>
            </div>

            {/* Decorative Elements */}
            <div className="absolute -z-10 -bottom-4 -right-4 w-full h-full bg-gradient-to-br from-primary/20 to-primary/5 rounded-3xl" />
            <div className="absolute -z-20 -bottom-8 -right-8 w-full h-full bg-gradient-to-br from-primary/10 to-transparent rounded-3xl" />
          </div>
        </div>
      </div>
    </section>
  )
}

